mapper.select:
SELECT /* dupBook */
       COUNT(*)
  FROM TM_BKINFO
 WHERE BOOK_ISBN = #{bookIsbn}
   AND LANG_CODE = #{langCode}

SELECT /* getBookNumbByIsbn */
       BOOK_NUMB
  FROM TM_BKINFO
 WHERE BOOK_ISBN = #{bookIsbn}
   AND LANG_CODE = #{langCode}

mapper.insert:
/* setBook */
INSERT INTO TM_BKINFO (
            BOOK_ISBN
          , LANG_CODE
          , BOOK_TITL
          , BOOK_ATHR
          , BOOK_PUBL
          , BOOK_CVIM
          , BOOK_DESC
          , PUBL_DATE
) VALUES (  #{bookIsbn}
          , #{langCode}
          , #{bookTitl}
          , REPLACE(#{bookAthr}, '^', ', ')
          , #{bookPubl}
          , #{bookCvim}
          , #{bookDesc}
          , #{publDate}
)
